import unittest
from candidate import sort_even

class TestSortEven(unittest.TestCase):
    def test_sort_even_single_element(self):
        self.assertEqual(sort_even([1]), [1])

    def test_sort_even_two_elements(self):
        self.assertEqual(sort_even([1, 2]), [1, 2])

    def test_sort_even_three_elements(self):
        self.assertEqual(sort_even([1, 2, 3]), [1, 2, 3])

    def test_sort_even_four_elements(self):
        self.assertEqual(sort_even([5, 6, 3, 4]), [3, 6, 5, 4])

    def test_sort_even_five_elements(self):
        self.assertEqual(sort_even([5, 6, 3, 4, 1]), [3, 6, 5, 4, 1])

    def test_sort_even_empty_list(self):
        self.assertEqual(sort_even([]), [])

    def test_sort_even_none_input(self):
        with self.assertRaises(TypeError):
            sort_even(None)

    def test_sort_even_non_list_input(self):
        with self.assertRaises(TypeError):
            sort_even('1234')

    def test_sort_even_list_with_none(self):
        with self.assertRaises(TypeError):
            sort_even([1, 2, None, 4])

    def test_sort_even_list_with_non_integer(self):
        with self.assertRaises(TypeError):
            sort_even([1, 2, '3', 4])
